1	/** Same-owner private Read composition with source conditions for canonical
2	 * current points, Type inventory and initial Resource/incident-Link reads. The service owns finite
3	 * waits; continuation minimums, receipt serving and replication Snapshots are
4	 * separate contracts. */
5	import {
6	  checkCurrentReadMinimum,
7	  snapshotCurrentReadMinimum,
8	  TransactionMinimumFailure,
9	  type TransactionMinimum,
10	} from "./transaction-consistency.js";
11	import { isProxy } from "node:util/types";
12	import {
13	  createAuthorityReadPlane,
14	  AuthorityReadError,
15	  type AuthorityReadDeliveryOptions,
16	  type AuthorityReadOptions,
17	  type AuthorityReadPlane,
18	  type AuthorityReadFacet,
19	  type AuthorityReadResult,
20	  type AuthorityAliasResult,
21	  type ReadObservation,
22	} from "./authority-read.js";
23	import type { ReadRequest } from "@bdp/protocol";
24	import type { TransactionReadContext } from "./transaction-store.js";
25	import type { openTransactionStore } from "./transaction-store.js";
26	
27	export class TransactionMinimumVisibilityGap extends Error {}
28	
29	/** Current private minimum subset; full request validation remains with Read. */
30	export function isCurrentTransactionMinimumRead(request: ReadRequest, scope: string): boolean {
31	  if (isProxy(request)) return false;
32	  switch (request.kind) {
33	    case "resource": {
34	      if (request.resource !== "type")
35	        return request.resource === "bead" || request.resource === "link";
36	      // Locality is checked before Read captures the request. Do not execute
37	      // an ID getter or method here; canonical syntax remains Read's decision.
38	      const id = Object.getOwnPropertyDescriptor(request, "id");
39	      return (
40	        id !== undefined &&
41	        "value" in id &&
42	        typeof id.value === "string" &&
43	        id.value.startsWith(scope)
44	      );
45	    }
46	    case "properties":
47	      return request.resource === "bead" || request.resource === "link";
48	    case "collection":
49	      return (
50	        (request.collection === "beads" ||
51	          request.collection === "links" ||
52	          request.collection === "types") &&
53	        request.continuation === undefined
54	      );
55	    case "bead-links":
56	      return request.continuation === undefined;
57	    default:
58	      return false;
59	  }
60	}
61	
62	/** Capture route fields before any receiving signal callback can mutate the caller's
63	 * request. Preserve rejected descriptors/prototypes for the authority's own
64	 * receiving path; never invoke a getter while making this private snapshot. */
65	export function captureTransactionReadRequest<O extends ReadRequest>(request: O): O {
66	  if (request === null || typeof request !== "object" || isProxy(request)) return request;
67	  return Object.freeze(
68	    Object.create(Object.getPrototypeOf(request), Object.getOwnPropertyDescriptors(request)),
69	  ) as O;
70	}
71	
72	function dataOnlyReadRequest(request: ReadRequest): boolean {
73	  if (request === null || typeof request !== "object" || isProxy(request) || Array.isArray(request))
74	    return false;
75	  const prototype = Object.getPrototypeOf(request);
76	  return (
77	    (prototype === Object.prototype || prototype === null) &&
78	    Reflect.ownKeys(request).every((key) => {
79	      const field = Object.getOwnPropertyDescriptor(request, key);
80	      return typeof key === "string" && field !== undefined && "value" in field;
81	    })
82	  );
83	}
84	
85	/** Classify only own data fields. Authority receiving still validates the full request. */
86	export function currentReadMinimumKind(
87	  request: ReadRequest,
88	): "resource" | "missing" | "initial-collection" | "type" | "initial-types" | "strict" {
89	  if (isProxy(request) || !request || typeof request !== "object") return "strict";
90	  const fields = Object.getOwnPropertyDescriptors(request);
91	  const data = (key: string): unknown => {
92	    const field = fields[key];
93	    return field && "value" in field ? field.value : undefined;
94	  };
95	  if (
96	    (data("kind") === "resource" || data("kind") === "properties") &&
97	    (data("resource") === "bead" || data("resource") === "link")
98	  )
99	    return "resource";
100	  if (data("kind") === "bead-links" && data("continuation") === undefined) return "missing";
101	  if (data("kind") === "resource" && data("resource") === "type") return "type";
102	  if (
103	    data("kind") === "collection" &&
104	    data("collection") === "types" &&
105	    data("continuation") === undefined
106	  )
107	    return "initial-types";
108	  if (
109	    data("kind") === "collection" &&
110	    (data("collection") === "beads" || data("collection") === "links") &&
111	    data("continuation") === undefined
112	  )
113	    return "initial-collection";
114	  return "strict";
115	}
116	type MinimumCondition = Readonly<{
117	  minimum: TransactionMinimum;
118	  kind: ReturnType<typeof currentReadMinimumKind> | "alias";
119	}>;
120	const minimumConditions = new WeakSet<object>();
121	function minimumCondition(
122	  minimum: TransactionMinimum,
123	  kind: MinimumCondition["kind"],
124	): MinimumCondition {
125	  const condition = Object.freeze({ minimum, kind });
126	  minimumConditions.add(condition);
127	  return condition;
128	}
129	function capturedCondition(value: unknown): MinimumCondition {
130	  if (!value || typeof value !== "object" || !minimumConditions.has(value))
131	    throw new TypeError("unrecognized private minimum condition");
132	  return value as MinimumCondition;
133	}
134	
135	/** Preserve the authority's data-only option boundary while ignoring only the
136	 * ordinary facet's sourceCondition. Signal validation stays with the authority. */
137	function ordinaryDeliveryOptions(
138	  options: AuthorityReadDeliveryOptions | undefined,
139	): AuthorityReadDeliveryOptions | undefined {
140	  if (options === undefined) return undefined;
141	  if (options === null || typeof options !== "object" || isProxy(options) || Array.isArray(options))
142	    throw new AuthorityReadError(
143	      "invalid-input",
144	      "Read delivery options must be a plain data object",
145	    );
146	  const prototype = Object.getPrototypeOf(options);
147	  if (prototype !== Object.prototype && prototype !== null)
148	    throw new AuthorityReadError(
149	      "invalid-input",
150	      "Read delivery options must have a plain prototype",
151	    );
152	  let signal: PropertyDescriptor | undefined;
153	  let unknownKey = false;
154	  for (const key of Reflect.ownKeys(options)) {
155	    if (typeof key !== "string")
156	      throw new AuthorityReadError(
157	        "invalid-input",
158	        "Read delivery options cannot have symbol fields",
159	      );
160	    const descriptor = Object.getOwnPropertyDescriptor(options, key);
161	    if (descriptor === undefined || !("value" in descriptor))
162	      throw new AuthorityReadError("invalid-input", "Read delivery options cannot have accessors");
163	    if (key !== "signal" && key !== "sourceCondition") unknownKey = true;
164	    if (key === "signal") signal = descriptor;
165	  }
166	  if (unknownKey) throw new AuthorityReadError("invalid-input", "unknown Read delivery option");
167	  return signal === undefined ? undefined : { signal: signal.value };
168	}
169	
170	/** Source-private minimum-read receiving snapshot. Only authority-rejected option or
171	 * signal shapes throw; callers retain authority error/lifecycle delivery on that
172	 * path. The configured minimum replaces the caller's opaque condition value. */
173	export function captureTransactionReadDeliveryOptions(
174	  options: AuthorityReadDeliveryOptions | undefined,
175	): AuthorityReadDeliveryOptions | undefined {
176	  const captured = ordinaryDeliveryOptions(options);
177	  const signal = captured?.signal;
178	  if (
179	    signal !== undefined &&
180	    (typeof signal !== "object" ||
181	      signal === null ||
182	      isProxy(signal) ||
183	      !(signal instanceof AbortSignal))
184	  )
185	    throw new AuthorityReadError("invalid-input", "Read signal must be an AbortSignal");
186	  return captured === undefined ? undefined : Object.freeze(captured);
187	}
188	
189	export type TransactionReadOptions = Pick<
190	  AuthorityReadOptions,
191	  "selectorLimits" | "pagination" | "advertisedLimits"
192	>;
193	
194	/** The caller owns the store lifetime. Closing the plane invalidates its cursors
195	 * but does not close or replace the mutation owner. Configuration is fixed for
196	 * this private store's lifetime and is captured through its guarded entry. */
197	export function createTransactionReadPlane(
198	  owner: ReturnType<typeof openTransactionStore>,
199	  options: TransactionReadOptions,
200	) {
201	  const configuration = owner.readConfiguration();
202	  const plane = createAuthorityReadPlane({
203	    entry: owner,
204	    scopeEpoch: configuration.scopeEpoch,
205	    installedTypes: configuration.installedTypes,
206	    scopeConfiguration: {
207	      capture: (reader) => ({
208	        ...configuration.scopeConfiguration,
209	        policyIdentity: owner.captureReadAuthorization(reader, { kind: "anonymous" })
210	          .authorizationView,
211	      }),
212	    },
213	    selectorLimits: options.selectorLimits,
214	    pagination: options.pagination,
215	    advertisedLimits: options.advertisedLimits,
216	    checkSourceCondition: (condition, observation, refusal) => {
217	      // Preserve the initial collection's already-materialized request-control
218	      // Problem. It is not a representation whose minimum can be satisfied.
219	      if (refusal?.code === "invalid-parameter" || refusal?.code === "limit-exceeded") return;
220	      const { minimum, kind } = capturedCondition(condition);
221	      const current = transactionReadContexts(observation).current;
222	      if (refusal?.code === "resource-not-found") {
223	        if (kind === "resource" || kind === "missing" || kind === "alias") return;
224	        if (kind === "type") {
225	          checkCurrentReadMinimum(minimum, current, true);
226	          return;
227	        }
228	        try {
229	          checkCurrentReadMinimum(minimum, current, false);
230	          return;
231	        } catch (error) {
232	          // Only simultaneous missing/consistency failures remain unqualified.
233	          if (
234	            error instanceof TransactionMinimumFailure &&
235	            (error.reason === "behind" ||
236	              error.reason === "foreign-view" ||
237	              error.reason === "cursor-expired")
238	          )
239	            throw new TransactionMinimumVisibilityGap(
240	              "minimum-position visibility ordering unqualified",
241	            );
242	          throw error;
243	        }
244	      }
245	      checkCurrentReadMinimum(minimum, current, kind !== "strict");
246	    },
247	    captureReadAuthorization: (reader, principal) => {
248	      const policy = owner.captureReadAuthorization(reader, principal);
249	      return {
250	        kind: "authorized",
251	        authorization: {
252	          scopeEpoch: configuration.scopeEpoch,
253	          authorizationView: policy.authorizationView,
254	          policy: { canRead: () => policy.readPolicy === "all-visible" },
255	          canReadType: () => policy.readPolicy === "all-visible",
256	        },
257	      };
258	    },
259	  });
260	  const checked = <Result extends AuthorityReadResult<ReadRequest> | AuthorityAliasResult>(
261	    result: Result,
262	  ): Result => {
263	    if ("observation" in result) transactionReadContexts(result.observation);
264	    return result;
265	  };
266	  const observe = <T>(promise: Promise<T>): Promise<T> => {
267	    void promise.catch(() => {});
268	    return promise;
269	  };
270	  const composed: AuthorityReadPlane = {
271	    closed: plane.closed,
272	    close: () => plane.close(),
273	    readFor(principal) {
274	      const facet = plane.readFor(principal);
275	      return {
276	        perform: (request, options) => {
