  }
  function receipt(
    principal: string,
    id: string,
    minimum?: TransactionMinimum,
  ): ReceiptObservation | Extract<TransactionServiceReceiptResult, { readonly status: 404 }> {
    const observed = owner.readReceipt(principal, id, minimum);
    return observed.receipt === undefined
