373	      const policyIdentity = transactionRuntimeDigest({
374	        revision: "transaction-policy-1",
375	        view: actual.authorizationView,
376	        read: actual.authorization.readPolicy,
377	        aggregate: actual.scopeConfiguration.maximumEndpointMultiplicity,
378	        associations,
379	      });
380	      const runtimeConfigurationIdentity = transactionRuntimeDigest({
381	        revision: "transaction-runtime-1",
382	        scope,
383	        artifactIdentity: contracts.identity,
384	        settings,
385	        authorityMode,
386	        policyIdentity,
387	        authenticationIdentity,
388	        profile: "transactional",
389	        history: false,
390	      });
391	      return Object.freeze({
392	        authorityMode,
393	        runtimeConfigurationIdentity,
394	        artifactIdentity: contracts.identity,
395	        policyIdentity,
396	        authenticationIdentity,
397	        scope,
398	        profile: "transactional" as const,
399	        history: false as const,
400	        claimEligible: false as const,
401	      });
402	    },
403	  });
404	}
