        expect(checkedProblem(await body(refused))).toMatchObject({
          status,
          code: status === 503 ? "catch-up-timeout" : status === 410 ? "cursor-expired" : "foreign-view",
        });
      } else {
        expect(refused.status).toBe(404);
        assertContext(refused);
        expect(checkedProblem(await body(refused))).toMatchObject({ code: "resource-not-found" });
      }
