    expect(response.headers.get("retry-after")).toBe("1");
    expect(response.headers.get("bdp-scope-position")).toBe("pos-1");
    expect(response.headers.get("bdp-scope-epoch")).toBe(tuple["bdp-scope-epoch"]);
