    finally { clearTimeout(closeTimer); }
    if (closed) rmSync(directory, { recursive: true, force: true });
    console.log(JSON.stringify({ observation: "current-observation-http", elapsedMs: performance.now() - started, attempted, responses, waits, clockCalls: tick, closed, directory, directoryAbsent: !existsSync(directory), failureCount: failures.length }));
  }
  if (failures.length) throw new AggregateError(failures, "current observation HTTP and cleanup failed");
});
